import z3
import itertools

n = 20
colors = 4

# Edge variables
e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = z3.Bool(f"e_{i}_{j}")

# Color variables: integer 0..3
c = [z3.Int(f"c_{i}") for i in range(n)]

solver = z3.Solver()

# Color bounds
for i in range(n):
    solver.add(c[i] >= 0, c[i] <= colors-1)

# Edge implies different colors
for i in range(n):
    for j in range(i+1, n):
        solver.add(z3.Implies(e[(i,j)], c[i] != c[j]))

# At least 37 edges
edge_vars = [e[(i,j)] for i in range(n) for j in range(i+1, n)]
solver.add(z3.Sum([z3.If(v, 1, 0) for v in edge_vars]) >= 37)

#alen 3 cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(z3.Not(z3.And(e[(i,j)], e[(j,k)], e[(i,k)])))

print("Adding cycle constraints...")
# 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k == i or k == j:
                continue
            for l in range(k+1, n):
                if l == i or l == j:
                    continue
                # i-j-k-l-i
                # edges: (i,j), (j,k), (k,l), (i,l)
                # need to handle ordering
                edges_4 = []
                edges_4.append(e[(min(i,j), max(i,j))])
                edges_4.append(e[(min(j,k), max(j,k))])
                edges_4.append(e[(min(k,l), max(k,l))])
                edges_4.append(e[(min(i,l), max(i,l))])
                solver.add(z3.Not(z3.And(*edges_4)))

print("Added 4-cycle constraints...")
print("Checking...")
result = solver.check()
print(f"Result: {result}")

