n = 20
colors = 4

# Edge variables
e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = z3.Bool(f"e_{i}_{j}")

# Color variables: integer 0..3
c = [z3.Int(f"c_{i}") for i in range(n)]

solver = z3.Solver()

# Color bounds
for i in range(n):
    solver.add(c[i] >= 0, c[i] <= colors-1)

# Edge implies different colors
for i in range(n):
    for j in range(i+1, n):
        solver.add(z3.Implies(e[(i,j)], c[i] != c[j]))

# At least 37 edges
edge_vars = [e[(i,j)] for i in range(n) for j in range(i+1, n)]
solver.add(z3.Sum([z3.If(v, 1, 0) for v in edge_vars]) >= 37)

# We'll add cycle constraints lazily
# First, add triangle constraints (they are few: C(20,3)=1140)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(z3.Not(z3.And(e[(i,j)], e[(j,k)], e[(i,k)])))

print("Added triangle constraints")

# Now let's try to solve and then check for short cycles
print("Solving...")
result = solver.check()
print(f"Result: {result}")

if str(result) == "sat":
    m = solver.model()
    # Build adjacency
    adj = [set() for _ in range(n)]
    for (i,j), var in e.items():
        val = m[var]
        if val is not None and z3.is_true(val):
            adj[i].add(j)
            adj[j].add(i)

    # Count edges
    edge_count = sum(len(adj[i]) for i in range(n)) // 2
    print(f"Edges: {edge_count}")

    # Check for short cycles using BFS
    def find_short_cycle(adj, max_len=6):
        # BFS from each vertex, looking for cycles
        for start in range(n):
            # BFS
            parent = [-1] * n
            dist = [-1] * n
            queue = [start]
            dist[start] = 0
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                    elif v != parent[u] and parent[v] != u:
                        # Found a cycle
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len <= max_len:
                            return (start, u, v, cycle_len)
        return None

    cycle = find_short_cycle(adj, 6)
    if cycle:
        print(f"Found short cycle: {cycle}")
    else:
        print("No short cycles found!")
        # Print edges
        edges_list = []
        for i in range(n):
            for j in adj[i]:
                if i < j:
                    edges_list.append((i,j))
        print(f"Edges: {edges_list}")
        # Print colors
        colors_list = [m[c[i]].as_long() for i in range(n)]
        print(f"Colors: {colors_list}")
else:
    print("Unsatisfiable")
